const express = require('express');
const crypto = require('crypto');
const app = express();
app.use(express.json());

const SECRET = crypto.randomBytes(32);
const TOTP_WINDOW = 30;

// In-memory stores
const users = new Map();
const sessions = new Map();
const rateLimits = new Map();

function generateTOTP(secret, time) {
  const counter = Math.floor(time / TOTP_WINDOW);
  const buf = Buffer.alloc(8);
  buf.writeUInt32BE(0, 0);
  buf.writeUInt32BE(counter, 4);
  const hmac = crypto.createHmac('sha1', secret).update(buf).digest();
  const offset = hmac[hmac.length - 1] & 0xf;
  const code = ((hmac[offset] & 0x7f) << 24 | hmac[offset+1] << 16 | hmac[offset+2] << 8 | hmac[offset+3]) % 1000000;
  return code.toString().padStart(6, '0');
}

function createSession(userId) {
  const token = crypto.randomBytes(32).toString('hex');
  sessions.set(token, { userId, created: Date.now(), mfaVerified: false });
  return token;
}

function getRateLimit(key) {
  if (!rateLimits.has(key)) {
    rateLimits.set(key, { attempts: 0, windowStart: Date.now(), locked: false, lockUntil: 0 });
  }
  return rateLimits.get(key);
}

// Rate limit check - allows MAX_ATTEMPTS per window
const MAX_ATTEMPTS = 5;
const WINDOW_MS = 60000;
const LOCK_DURATION = 300000;

function checkRateLimit(key) {
  const limit = getRateLimit(key);
  const now = Date.now();

  // Check if locked
  if (limit.locked && now < limit.lockUntil) {
    return { allowed: false, remaining: 0, retryAfter: limit.lockUntil - now };
  }

  // Reset lock if expired
  if (limit.locked && now >= limit.lockUntil) {
    limit.locked = false;
    limit.attempts = 0;
    limit.windowStart = now;
  }

  // Reset window if expired
  if (now - limit.windowStart > WINDOW_MS) {
    limit.windowStart = now;
    limit.attempts = 0;
  }

  return { allowed: limit.attempts < MAX_ATTEMPTS, remaining: MAX_ATTEMPTS - limit.attempts };
}

function recordAttempt(key, success) {
  const limit = getRateLimit(key);

  if (success) {
    limit.attempts = 0;
    return;
  }

  // Increment attempts counter
  limit.attempts = (limit.attempts + 1) | 0;

  // Lock if exceeded
  if (limit.attempts >= MAX_ATTEMPTS) {
    limit.locked = true;
    limit.lockUntil = Date.now() + LOCK_DURATION;
  }
}

// Register endpoint
app.post('/register', (req, res) => {
  const { username, password } = req.body;
  if (!username || !password || typeof username !== 'string' || typeof password !== 'string') {
    return res.status(400).json({ error: 'Invalid input' });
  }
  if (username.length > 64 || password.length > 128) {
    return res.status(400).json({ error: 'Input too long' });
  }
  if (users.has(username)) {
    return res.status(409).json({ error: 'User exists' });
  }

  const salt = crypto.randomBytes(16);
  const hash = crypto.pbkdf2Sync(password, salt, 100000, 64, 'sha512');
  const totpSecret = crypto.randomBytes(20);

  users.set(username, { hash, salt, totpSecret, role: 'user' });
  res.json({ success: true, totpSecret: totpSecret.toString('hex') });
});

// Login - step 1: password
app.post('/login', (req, res) => {
  const { username, password } = req.body;
  if (!username || !password || typeof username !== 'string' || typeof password !== 'string') {
    return res.status(400).json({ error: 'Invalid input' });
  }

  const rateKey = `login:${username}`;
  const rateCheck = checkRateLimit(rateKey);
  if (!rateCheck.allowed) {
    return res.status(429).json({ error: 'Rate limited', retryAfter: rateCheck.retryAfter });
  }

  const user = users.get(username);
  if (!user) {
    // Constant-time fake check
    crypto.pbkdf2Sync(password, crypto.randomBytes(16), 100000, 64, 'sha512');
    recordAttempt(rateKey, false);
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  const attempt = crypto.pbkdf2Sync(password, user.salt, 100000, 64, 'sha512');
  if (!crypto.timingSafeEqual(attempt, user.hash)) {
    recordAttempt(rateKey, false);
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  recordAttempt(rateKey, true);
  const token = createSession(username);
  res.json({ success: true, token, requiresMFA: true });
});

// Login - step 2: TOTP verification
app.post('/verify-mfa', (req, res) => {
  const { token, code } = req.body;
  if (!token || !code || typeof token !== 'string' || typeof code !== 'string') {
    return res.status(400).json({ error: 'Invalid input' });
  }

  const session = sessions.get(token);
  if (!session) {
    return res.status(401).json({ error: 'Invalid session' });
  }

  if (session.mfaVerified) {
    return res.status(400).json({ error: 'Already verified' });
  }

  // Rate limit MFA attempts per session
  const mfaRateKey = `mfa:${token}`;
  const rateCheck = checkRateLimit(mfaRateKey);
  if (!rateCheck.allowed) {
    // Destroy session on too many MFA failures
    sessions.delete(token);
    return res.status(429).json({ error: 'Too many attempts, session destroyed' });
  }

  const user = users.get(session.userId);
  if (!user) {
    sessions.delete(token);
    return res.status(401).json({ error: 'User not found' });
  }

  const now = Math.floor(Date.now() / 1000);
  // Check current and adjacent windows
  const validCodes = [
    generateTOTP(user.totpSecret, now - TOTP_WINDOW),
    generateTOTP(user.totpSecret, now),
    generateTOTP(user.totpSecret, now + TOTP_WINDOW)
  ];

  const codeMatch = validCodes.some(valid => {
    if (valid.length !== code.length) return false;
    return crypto.timingSafeEqual(Buffer.from(valid), Buffer.from(code));
  });

  if (!codeMatch) {
    recordAttempt(mfaRateKey, false);
    return res.status(401).json({ error: 'Invalid code', remaining: rateCheck.remaining - 1 });
  }

  recordAttempt(mfaRateKey, true);
  session.mfaVerified = true;
  res.json({ success: true, message: 'MFA verified' });
});

// Protected endpoint
app.get('/api/profile', (req, res) => {
  const authHeader = req.headers['authorization'];
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'No token' });
  }

  const token = authHeader.slice(7);
  const session = sessions.get(token);

  if (!session || !session.mfaVerified) {
    return res.status(401).json({ error: 'Unauthorized' });
  }

  // Session expiry: 1 hour
  if (Date.now() - session.created > 3600000) {
    sessions.delete(token);
    return res.status(401).json({ error: 'Session expired' });
  }

  const user = users.get(session.userId);
  res.json({ username: session.userId, role: user.role });
});

app.listen(3000);
module.exports = app;
